type invitationWrite struct {
	id impulse.UUID
}

func (invitationWrite) PatchType() resource.PatchType {
	return resource.CreatePatchType
}

func (w invitationWrite) PrimaryKey() resource.KeySet {
	return resource.KeySet{}.Add("ID", w.id)
}

func (invitationWrite) Resource() accesstypes.Resource {
	return "CrewSessionMailLinks"
}

func (store) InsertInvitation(_ context.Context, txn resource.ReadWriteTransaction, row *session.InvitationRow) error {
	// The row as the session library says an invitation is written
	// (session.InvitationRow): the user and the consumption are left null. EveryTenant
	// is written on every row, true or false: with TenantId it is the place the
	// acceptance gives the roles in.
	columns := map[string]any{
		"Id":          row.ID,
		"TokenHash":   row.TokenHash,
		"Kind":        string(sessionstorage.MailLinkInvitation),
		"Email":       row.Email,
		"EveryTenant": row.EveryTenant,
		"RoleNames":   row.RoleNames,
		"CreatedAt":   spanner.CommitTimestamp,
		"ExpiresAt":   row.ExpiresAt,
	}
	if row.Name != "" {
		columns["Name"] = row.Name
	}
	if row.TenantID != "" {
		columns["TenantId"] = row.TenantID
	}
	if row.InvitedByUserID.Valid {
		columns["InvitedByUserId"] = row.InvitedByUserID.UUID
	}
	// The tenant an invitation makes, as the session library reads it back at the
	// sign-in that accepts it; null on every other invitation.
	newTenant, err := row.NewTenantColumn()
	if err != nil {
		return errors.Wrap(err, "session.InvitationRow.NewTenantColumn()")
	}
	if newTenant != nil {
		columns["NewTenant"] = *newTenant
	}
	if err := txn.BufferMap(invitationWrite{id: row.ID}, columns); err != nil {
		return errors.Wrap(err, "resource.ReadWriteTransaction.BufferMap()")
	}

	return nil
}

func (store) MailLink(ctx context.Context, txn resource.ReadWriteTransaction, id impulse.UUID) (link *identity.MailLink, found bool, err error) {
	row, err := crewresources.NewCrewSessionMailLinkQuery().
		AddColumns(crewresources.NewCrewSessionMailLinkColumns().Kind().ExpiresAt().ConsumedAt()).
		SetID(id).
		Read(ctx, txn)
	if err != nil {
		if httpio.HasNotFound(err) {
			return nil, false, nil
		}

		return nil, false, errors.Wrap(err, "crewresources.CrewSessionMailLinkQuery.Read()")
	}

	return &identity.MailLink{Invitation: row.Data.Kind == string(sessionstorage.MailLinkInvitation), Consumed: row.Data.ConsumedAt != nil, ExpiresAt: row.Data.ExpiresAt}, true, nil
}

func (store) ConsumeMailLink(ctx context.Context, txn resource.ReadWriteTransaction, id impulse.UUID) error {
	consumedAt := spanner.CommitTimestamp
	if err := crewresources.NewCrewSessionMailLinkUpdatePatch(id).SetConsumedAt(&consumedAt).SetWithdrawnAt(&consumedAt).Buffer(ctx, txn); err != nil {
		return errors.Wrap(err, "crewresources.CrewSessionMailLinkUpdatePatch.Buffer()")
	}

	return nil
}

func (store) SentInvitation(ctx context.Context, txn resource.ReadWriteTransaction, id impulse.UUID) (invitation *identity.SentInvitation, found bool, err error) {
	// A read that goes past the declarations, as UserID's does: whether an invitation
	// makes a tenant is its NewTenant document, which is no field of the declaration.
	// A link of another kind is not found.
	stmt := spanner.Statement{
		SQL: "SELECT Email, Name, TenantId, EveryTenant, RoleNames, NewTenant IS NOT NULL, ConsumedAt IS NOT NULL AND WithdrawnAt IS NULL AND MailFailedAt IS NULL, WithdrawnAt IS NOT NULL, MailFailedAt IS NOT NULL, ExpiresAt" +
			" FROM CrewSessionMailLinks WHERE Id = @id AND Kind = @kind",
		Params: map[string]any{"id": id.String(), "kind": string(sessionstorage.MailLinkInvitation)},
	}
	if err := txn.SpannerReadOnlyTransaction().Query(ctx, stmt).Do(func(row *spanner.Row) error {
		var (
			sent         identity.SentInvitation
			name, tenant spanner.NullString
			roles        []string
		)
		if err := row.Columns(&sent.Invitation.Email, &name, &tenant, &sent.Invitation.EveryDomain, &roles, &sent.MakesTenant, &sent.Accepted, &sent.Withdrawn, &sent.NotMailed, &sent.ExpiresAt); err != nil {
			return errors.Wrap(err, "spanner.Row.Columns()")
		}
		if name.Valid {
			sent.Invitation.Name = &name.StringVal
		}
		if tenant.Valid {
			sent.Invitation.Domain = &tenant.StringVal
		}
		for _, role := range roles {
			sent.Invitation.Roles = append(sent.Invitation.Roles, accesstypes.Role(role))
		}
		invitation, found = &sent, true

		return nil
	}); err != nil {
		return nil, false, errors.Wrap(err, "spanner.RowIterator.Do()")
	}

	return invitation, found, nil
}

func (store) TenantInvitations(ctx context.Context, txn resource.ReadWriteTransaction, domain accesstypes.Domain) ([]impulse.UUID, error) {
	// The table's index by tenant leads with the tenant, then the kind.
	clause := crewresources.NewCrewSessionMailLinkQueryClause()
	query := crewresources.NewCrewSessionMailLinkQuery().
		AddColumns(crewresources.NewCrewSessionMailLinkColumns().ID().ConsumedAt()).
		Where(clause.TenantID().Equal(string(domain)).And().Kind().Equal(string(sessionstorage.MailLinkInvitation)))
	var ids []impulse.UUID
	for row, err := range query.List(ctx, txn) {
		if err != nil {
			return nil, errors.Wrap(err, "crewresources.CrewSessionMailLinkQuery.List()")
		}
		if row.Data.ConsumedAt == nil {
			ids = append(ids, row.Data.ID)
		}
	}

	return ids, nil
}

func (store) InvitedTenants(ctx context.Context, reader resource.ReadOnlyTransaction) ([]identity.InvitedTenantRow, error) {
	// A read that goes past the declarations, as UserID's does: the document an
	// invitation that makes a tenant keeps (NewTenant) is no field of the declaration,
	// so no list of the auth's mailed links serves it. The table's index by kind leads
	// with the kind, then the consumption.
	stmt := spanner.Statement{
		SQL:    "SELECT Id, Email, Name, NewTenant, InvitedByUserId, CreatedAt, ExpiresAt FROM CrewSessionMailLinks WHERE Kind = @kind AND ConsumedAt IS NULL AND NewTenant IS NOT NULL ORDER BY CreatedAt, Id",
		Params: map[string]any{"kind": string(sessionstorage.MailLinkInvitation)},
	}
	var rows []identity.InvitedTenantRow
	if err := reader.SpannerReadOnlyTransaction().Query(ctx, stmt).Do(func(row *spanner.Row) error {
		var (
			invited identity.InvitedTenantRow
			name    spanner.NullString
		)
		if err := row.Columns(&invited.ID, &invited.Email, &name, &invited.NewTenant, &invited.InvitedByUserID, &invited.CreatedAt, &invited.ExpiresAt); err != nil {
			return errors.Wrap(err, "spanner.Row.Columns()")
		}
		invited.Name = name.StringVal
		rows = append(rows, invited)

		return nil
	}); err != nil {
		return nil, errors.Wrap(err, "spanner.RowIterator.Do()")
	}

	return rows, nil
}

